package android.app;
public class DatePickerDialog extends AlertDialog { public interface OnDateSetListener { void onDateSet(android.widget.DatePicker view,int year,int month,int dayOfMonth); } private final android.widget.DatePicker picker; public DatePickerDialog(android.content.Context c,OnDateSetListener listener,int year,int month,int day) { super(c); picker=new android.widget.DatePicker(c); setView(picker); } public DatePickerDialog(android.content.Context c,int theme,OnDateSetListener listener,int year,int month,int day) { this(c,listener,year,month,day); } public android.widget.DatePicker getDatePicker() { return picker; } public void updateDate(int year,int month,int day) {} }
